css:
.mo5-flip-grid{
  --mo5-fg-ink:#e9edf7; --mo5-fg-dim:#8290a8; --mo5-fg-line:rgba(255,255,255,.09);
  --mo5-fg-a:#6ee7ff; --mo5-fg-b:#c084fc;
  position:relative; box-sizing:border-box; width:100%; max-width:340px; height:150px;
  padding:9px 10px 10px; border:1px solid var(--mo5-fg-line); border-radius:14px;
  background:radial-gradient(130% 150% at 10% -10%, #1b2434 0%, #0f131c 60%);
  color:var(--mo5-fg-ink); font-family:ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;
  overflow:hidden; -webkit-tap-highlight-color:transparent;
}
.mo5-flip-grid-head{display:flex; align-items:center; gap:6px; height:13px; margin-bottom:8px}
.mo5-flip-grid-pip{width:6px; height:6px; border-radius:50%; background:var(--mo5-fg-a); animation:mo5-flip-grid-pulse 2.2s ease-out infinite}
.mo5-flip-grid-kick{font-size:9.5px; font-weight:700; letter-spacing:.14em; text-transform:uppercase}
.mo5-flip-grid-hint{margin-left:auto; font-size:9px; color:var(--mo5-fg-dim); letter-spacing:.03em}
.mo5-flip-grid-cells{
  display:grid; grid-template-columns:repeat(3,1fr); grid-template-rows:repeat(2,1fr); gap:6px;
  height:calc(100% - 21px);
  transition:transform .46s cubic-bezier(.22,1,.36,1), opacity .3s ease, filter .3s ease;
}
.mo5-flip-grid-cells[data-hide="1"]{transform:scale(.93); opacity:0; filter:blur(4px); pointer-events:none}
.mo5-flip-grid-tile{
  position:relative; box-sizing:border-box; display:flex; flex-direction:column; align-items:flex-start;
  justify-content:space-between; gap:2px; padding:6px 7px; margin:0; overflow:hidden;
  border:1px solid var(--mo5-fg-line); border-radius:10px; background:linear-gradient(165deg,#1c2432,#141a25);
  color:inherit; font:inherit; text-align:left; cursor:pointer;
  animation:mo5-flip-grid-pop .62s cubic-bezier(.22,1.18,.36,1) backwards;
  animation-delay:calc(var(--mo5-fg-i,0) * 55ms);
  transition:transform .26s cubic-bezier(.2,.9,.3,1.35), border-color .22s ease, box-shadow .22s ease;
}
.mo5-flip-grid-tile:hover{transform:translateY(-3px); border-color:rgba(110,231,255,.42); box-shadow:0 10px 18px -12px #000}
.mo5-flip-grid-tile:active{transform:translateY(-1px) scale(.965)}
.mo5-flip-grid-tile:focus-visible{outline:2px solid var(--mo5-fg-a); outline-offset:2px}
.mo5-flip-grid-sq{
  width:13px; height:13px; border-radius:4px; flex:none;
  background:linear-gradient(140deg,var(--mo5-fg-a),var(--mo5-fg-b)); box-shadow:0 0 10px -2px rgba(110,231,255,.75);
  animation:mo5-flip-grid-tilt 4.6s ease-in-out infinite; animation-delay:calc(var(--mo5-fg-i,0) * -.5s);
}
.mo5-flip-grid-nm{font-size:10px; font-weight:600; line-height:1}
.mo5-flip-grid-mini{
  width:100%; height:2px; border-radius:2px; transform:scaleX(var(--mo5-fg-p,.5)); transform-origin:0 50%;
  background:linear-gradient(90deg,var(--mo5-fg-a),var(--mo5-fg-b)); opacity:.75;
  animation:mo5-flip-grid-breathe 3.4s ease-in-out infinite; animation-delay:calc(var(--mo5-fg-i,0) * -.45s);
}
.mo5-flip-grid-detail{
  position:absolute; left:10px; right:10px; top:9px; bottom:10px; box-sizing:border-box; z-index:3;
  display:flex; flex-direction:column; padding:8px 10px 9px; opacity:0; visibility:hidden; pointer-events:none;
  border:1px solid rgba(110,231,255,.3); border-radius:12px;
  background:linear-gradient(155deg,#1f2937,#111722); box-shadow:0 20px 44px -24px #000;
  transform-origin:0 0; will-change:transform,opacity;
}
.mo5-flip-grid-detail[data-open="1"]{visibility:visible; pointer-events:auto}
.mo5-flip-grid-dtop{display:flex; align-items:center; gap:7px}
.mo5-flip-grid-dsq{width:15px; height:15px; border-radius:5px; background:linear-gradient(140deg,var(--mo5-fg-a),var(--mo5-fg-b)); box-shadow:0 0 14px -2px rgba(110,231,255,.8)}
.mo5-flip-grid-dnm{font-size:12.5px; font-weight:700; letter-spacing:.01em}
.mo5-flip-grid-back{
  margin-left:auto; box-sizing:border-box; padding:3px 9px; border:1px solid var(--mo5-fg-line); border-radius:99px;
  background:rgba(255,255,255,.05); color:var(--mo5-fg-dim); font:inherit; font-size:9.5px; cursor:pointer;
  transition:transform .2s cubic-bezier(.2,.9,.3,1.4), color .2s, background .2s;
}
.mo5-flip-grid-back:hover{color:var(--mo5-fg-ink); background:rgba(255,255,255,.1); transform:scale(1.06)}
.mo5-flip-grid-back:focus-visible{outline:2px solid var(--mo5-fg-a); outline-offset:2px}
.mo5-flip-grid-spark{display:block; width:100%; height:44px; margin:4px 0 2px; overflow:visible}
.mo5-flip-grid-path{filter:drop-shadow(0 0 6px rgba(110,231,255,.45))}
.mo5-flip-grid-dfoot{display:flex; align-items:baseline; gap:7px; margin-top:auto}
.mo5-flip-grid-dval{font-size:19px; font-weight:750; letter-spacing:-.02em; font-variant-numeric:tabular-nums}
.mo5-flip-grid-pct{font-size:11px; font-style:normal; color:var(--mo5-fg-dim); margin-left:1px}
.mo5-flip-grid-dsub{font-size:9px; color:var(--mo5-fg-dim)}
@keyframes mo5-flip-grid-pop{from{opacity:0; transform:translateY(12px) scale(.86)} to{opacity:1; transform:none}}
@keyframes mo5-flip-grid-pulse{0%{box-shadow:0 0 0 0 rgba(110,231,255,.55)} 70%{box-shadow:0 0 0 7px rgba(110,231,255,0)} 100%{box-shadow:0 0 0 0 rgba(110,231,255,0)}}
@keyframes mo5-flip-grid-tilt{0%,100%{transform:rotate(0) scale(1)} 50%{transform:rotate(45deg) scale(1.12)}}
@keyframes mo5-flip-grid-breathe{0%,100%{opacity:.45} 50%{opacity:.95}}
@media (prefers-reduced-motion: reduce){
  .mo5-flip-grid-tile,.mo5-flip-grid-sq,.mo5-flip-grid-pip,.mo5-flip-grid-mini{animation:none}
  .mo5-flip-grid-tile{opacity:1; transform:none}
  .mo5-flip-grid-cells,.mo5-flip-grid-detail{transition:none}
}

js:
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var cells = root.querySelector('.mo5-flip-grid-cells');
var detail = root.querySelector('.mo5-flip-grid-detail');
var back = root.querySelector('.mo5-flip-grid-back');
var dnm = root.querySelector('.mo5-flip-grid-dnm');
var dval = root.querySelector('.mo5-flip-grid-dval');
var spark = root.querySelector('.mo5-flip-grid-path');
var grad = root.querySelector('.mo5-flip-grid-grad');
var dtop = root.querySelector('.mo5-flip-grid-dtop');
var dfoot = root.querySelector('.mo5-flip-grid-dfoot');
var tiles = Array.prototype.slice.call(root.querySelectorAll('.mo5-flip-grid-tile'));
var last = null, busy = false, open = false;

var gid = 'mo5fg' + Math.random().toString(36).slice(2, 9);
if (grad) { grad.setAttribute('id', gid); if (spark) spark.setAttribute('stroke', 'url(#' + gid + ')'); }

var len = 300;
try { if (spark && spark.getTotalLength) len = spark.getTotalLength(); } catch (e) {}
spark.style.strokeDasharray = len + ' ' + len;
spark.style.strokeDashoffset = String(len);

function flip(from, to, done) {
  var dx = from.left - to.left, dy = from.top - to.top;
  var sx = from.width / Math.max(1, to.width), sy = from.height / Math.max(1, to.height);
  detail.style.transition = 'none';
  detail.style.transform = 'translate(' + dx + 'px,' + dy + 'px) scale(' + sx + ',' + sy + ')';
  detail.style.opacity = '0';
  void detail.offsetWidth;
  detail.style.transition = 'transform .58s cubic-bezier(.2,.92,.26,1.04), opacity .24s ease';
  detail.style.transform = 'translate(0px,0px) scale(1,1)';
  detail.style.opacity = '1';
  window.setTimeout(done, 600);
}

function stagger(nodes, delay) {
  if (reduce || !nodes[0] || !nodes[0].animate) return;
  for (var i = 0; i < nodes.length; i++) {
    nodes[i].animate(
      [{ opacity: 0, transform: 'translateY(9px)' }, { opacity: 1, transform: 'none' }],
      { duration: 420, delay: delay + i * 90, easing: 'cubic-bezier(.22,1,.36,1)', fill: 'backwards' }
    );
  }
}

function openTile(tile) {
  if (busy || open) return;
  last = tile; open = true;
  dnm.textContent = tile.getAttribute('data-name') || '';
  dval.childNodes[0].nodeValue = tile.getAttribute('data-val') || '';
  var f = tile.getBoundingClientRect();
  tiles.forEach(function (t) { t.tabIndex = -1; });
  detail.setAttribute('data-open', '1');
  detail.style.transition = 'none';
  detail.style.transform = 'none';
  var l = detail.getBoundingClientRect();
  cells.setAttribute('data-hide', '1');
  if (reduce) {
    detail.style.opacity = '1'; spark.style.strokeDashoffset = '0';
    back.focus(); return;
  }
  busy = true;
  flip(f, l, function () { busy = false; back.focus(); });
  stagger([dtop, dfoot], 180);
  spark.style.transition = 'none';
  spark.style.strokeDashoffset = String(len);
  void spark.getBoundingClientRect();
  spark.style.transition = 'stroke-dashoffset .85s cubic-bezier(.32,.9,.3,1) 220ms';
  spark.style.strokeDashoffset = '0';
}

function close() {
  if (busy || !open) return;
  open = false;
  tiles.forEach(function (t) { t.tabIndex = 0; });
  cells.setAttribute('data-hide', '0');
  if (reduce || !last) {
    detail.setAttribute('data-open', '0'); detail.style.opacity = '0';
    if (last) last.focus(); return;
  }
  busy = true;
  var f = last.getBoundingClientRect();
  var l = detail.getBoundingClientRect();
  var dx = f.left - l.left, dy = f.top - l.top;
  var sx = f.width / Math.max(1, l.width), sy = f.height / Math.max(1, l.height);
  detail.style.transition = 'transform .44s cubic-bezier(.5,0,.2,1), opacity .3s ease .1s';
  detail.style.transform = 'translate(' + dx + 'px,' + dy + 'px) scale(' + sx + ',' + sy + ')';
  detail.style.opacity = '0';
  window.setTimeout(function () {
    detail.setAttribute('data-open', '0');
    detail.style.transition = 'none';
    detail.style.transform = 'none';
    busy = false;
    if (last) last.focus();
  }, 450);
}

tiles.forEach(function (t) {
  t.addEventListener('click', function () { openTile(t); });
});
back.addEventListener('click', close);
root.addEventListener('keydown', function (e) { if (e.key === 'Escape' && open) { e.stopPropagation(); close(); } });

css:
.mo5-morph-pair{
  --mo5-mp-ink:#eef2fb; --mo5-mp-dim:#8b97ad; --mo5-mp-line:rgba(255,255,255,.08);
  --mo5-mp-a:#ff9f6e; --mo5-mp-b:#ff5f9e;
  box-sizing:border-box; position:relative; width:100%; max-width:340px; height:150px; padding:10px;
  display:flex; flex-direction:column; gap:6px;
  border:1px solid var(--mo5-mp-line); border-radius:14px;
  background:radial-gradient(120% 130% at 90% -20%, #26202c 0%, #10121a 62%);
  color:var(--mo5-mp-ink); font-family:ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;
  overflow:hidden; -webkit-tap-highlight-color:transparent;
}
.mo5-morph-pair-stage{position:relative; display:flex; gap:8px; flex:1; min-height:0}
.mo5-morph-pair-card{
  box-sizing:border-box; position:relative; margin:0; padding:7px 8px; cursor:pointer; overflow:hidden;
  border:1px solid rgba(255,159,110,calc(.1 + var(--mo5-mp-e,0) * .55)); border-radius:12px;
  background:linear-gradient(160deg, rgba(255,159,110,calc(.03 + var(--mo5-mp-e,0) * .1)), rgba(255,255,255,.02)), #171b26;
  color:inherit; font:inherit; text-align:left;
  box-shadow:0 calc(6px + var(--mo5-mp-e,0) * 10px) calc(14px + var(--mo5-mp-e,0) * 14px) -14px #000;
  transform:translateY(calc(var(--mo5-mp-e,0) * -3px)) scale(calc(.972 + var(--mo5-mp-e,0) * .028));
}
.mo5-morph-pair-card:focus-visible{outline:2px solid var(--mo5-mp-a); outline-offset:2px}
.mo5-morph-pair-a{flex:0 0 42%; display:grid; grid-template-columns:28px 1fr; grid-template-rows:auto auto auto; column-gap:7px; row-gap:2px; align-content:center}
.mo5-morph-pair-b{flex:1; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:2px}
.mo5-morph-pair-tag{
  font-size:8px; font-weight:700; letter-spacing:.14em; text-transform:uppercase;
  color:rgba(238,242,251,calc(.34 + var(--mo5-mp-e,0) * .6));
}
.mo5-morph-pair-a .mo5-morph-pair-tag{grid-column:1 / 3}
.mo5-morph-pair-slot{
  box-sizing:border-box; flex:none; border-radius:11px; border:1px dashed rgba(255,255,255,.16);
  opacity:var(--mo5-mp-slot,0); transition:opacity .25s ease;
}
.mo5-morph-pair-a .mo5-morph-pair-slot{width:28px; height:28px; grid-column:1; grid-row:2 / 4; align-self:center; border-radius:50%}
.mo5-morph-pair-b .mo5-morph-pair-slot{width:50px; height:50px; margin:2px 0 3px}
.mo5-morph-pair-t{font-size:12px; font-weight:700; letter-spacing:-.01em; line-height:1.1}
.mo5-morph-pair-a .mo5-morph-pair-t{grid-column:2; grid-row:2; align-self:end}
.mo5-morph-pair-s{font-size:8.5px; color:var(--mo5-mp-dim); letter-spacing:.05em; text-transform:uppercase}
.mo5-morph-pair-a .mo5-morph-pair-s{grid-column:2; grid-row:3}
.mo5-morph-pair-ghost{
  position:absolute; left:0; top:0; width:50px; height:50px; transform-origin:0 0; pointer-events:none; z-index:4;
  transform:translate(9px,41px) scale(.56);
  display:flex; align-items:flex-end; justify-content:center; padding-bottom:9px; box-sizing:border-box;
  border-radius:calc(var(--mo5-mp-r,14) * 1px);
  background:linear-gradient(150deg,var(--mo5-mp-a),var(--mo5-mp-b) 70%, #a855f7);
  box-shadow:0 10px 24px -10px rgba(255,95,158,.75), inset 0 1px 0 rgba(255,255,255,.35);
}
.mo5-morph-pair-eq{display:flex; align-items:flex-end; gap:2.5px; height:16px}
.mo5-morph-pair-bar{
  width:3px; height:16px; border-radius:2px; background:rgba(12,10,18,.72); transform-origin:50% 100%;
  animation:mo5-morph-pair-eq 1s ease-in-out infinite alternate;
  animation-delay:calc(var(--mo5-mp-j,0) * -.24s);
}
.mo5-morph-pair-foot{display:flex; align-items:center; gap:8px; height:14px}
.mo5-morph-pair-note{font-size:8.5px; color:var(--mo5-mp-dim); letter-spacing:.06em; text-transform:uppercase}
.mo5-morph-pair-track{position:relative; margin-left:auto; width:70px; height:4px; border-radius:99px; background:rgba(255,255,255,.09)}
.mo5-morph-pair-knob{
  position:absolute; left:0; top:-3px; width:10px; height:10px; border-radius:50%;
  background:linear-gradient(150deg,var(--mo5-mp-a),var(--mo5-mp-b));
  box-shadow:0 0 10px -1px rgba(255,95,158,.9);
  transform:translateX(calc(var(--mo5-mp-p,0) * 60px));
}
@keyframes mo5-morph-pair-eq{from{transform:scaleY(.25)} to{transform:scaleY(1)}}
@media (prefers-reduced-motion: reduce){
  .mo5-morph-pair-bar{animation:none; transform:scaleY(.6)}
}

js:
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var stage = root.querySelector('.mo5-morph-pair-stage');
var ghost = root.querySelector('.mo5-morph-pair-ghost');
var cards = Array.prototype.slice.call(root.querySelectorAll('.mo5-morph-pair-card'));
var slots = [
  root.querySelector('.mo5-morph-pair-a .mo5-morph-pair-slot'),
  root.querySelector('.mo5-morph-pair-b .mo5-morph-pair-slot')
];
var BASE = 50;
var geo = [{ x: 0, y: 0, s: .56 }, { x: 0, y: 0, s: 1 }];
var p = 0, v = 0, target = 0, last = 0, t0 = 0;

function measure() {
  var sr = stage.getBoundingClientRect();
  for (var i = 0; i < 2; i++) {
    var r = slots[i].getBoundingClientRect();
    geo[i] = { x: r.left - sr.left, y: r.top - sr.top, s: r.width / BASE };
  }
}

function lerp(a, b, k) { return a + (b - a) * k; }
function clamp01(n) { return n < 0 ? 0 : n > 1 ? 1 : n; }

function apply(k, bob) {
  var x = lerp(geo[0].x, geo[1].x, k);
  var y = lerp(geo[0].y, geo[1].y, k) + bob;
  var s = lerp(geo[0].s, geo[1].s, k);
  ghost.style.transform = 'translate(' + x.toFixed(2) + 'px,' + y.toFixed(2) + 'px) scale(' + s.toFixed(4) + ')';
  ghost.style.setProperty('--mo5-mp-r', String(lerp(BASE / 2, 14, clamp01(k))));
  var c = clamp01(k);
  cards[0].style.setProperty('--mo5-mp-e', String(1 - c));
  cards[1].style.setProperty('--mo5-mp-e', String(c));
  slots[0].style.setProperty('--mo5-mp-slot', String(c));
  slots[1].style.setProperty('--mo5-mp-slot', String(1 - c));
  root.style.setProperty('--mo5-mp-p', String(c));
}

function frame(now) {
  if (!root.isConnected) return;
  if (!t0) t0 = now;
  var dt = Math.min(.032, (now - last) / 1000 || .016);
  last = now;
  var k = 190, c = 21;
  var a = -k * (p - target) - c * v;
  v += a * dt; p += v * dt;
  if (Math.abs(p - target) < .0004 && Math.abs(v) < .004) { p = target; v = 0; }
  var bob = reduce ? 0 : Math.sin((now - t0) / 780) * 1.3;
  apply(p, bob);
  window.requestAnimationFrame(frame);
}

function goTo(i) {
  measure();
  target = i;
  if (reduce) { p = i; v = 0; apply(p, 0); }
  cards[0].setAttribute('aria-pressed', i === 0 ? 'true' : 'false');
  cards[1].setAttribute('aria-pressed', i === 1 ? 'true' : 'false');
  if (!reduce) {
    var pop = cards[i];
    if (pop.animate) pop.animate(
      [{ filter: 'brightness(1.5)' }, { filter: 'brightness(1)' }],
      { duration: 480, easing: 'cubic-bezier(.22,1,.36,1)' }
    );
  }
}

cards.forEach(function (c) {
  c.addEventListener('click', function () { goTo(Number(c.getAttribute('data-side'))); });
});
if (window.ResizeObserver) { new window.ResizeObserver(measure).observe(root); }
else { window.addEventListener('resize', measure); }

measure();
apply(0, 0);
if (reduce) { p = target = 1; apply(1, 0); cards[1].setAttribute('aria-pressed', 'true'); cards[0].setAttribute('aria-pressed', 'false'); }
else {
  window.requestAnimationFrame(frame);
  window.setTimeout(function () { if (root.isConnected && target === 0) goTo(1); }, 820);
}

css:
.mo5-iris-wipe{
  box-sizing:border-box; position:relative; width:100%; max-width:340px; height:150px;
  border-radius:14px; overflow:hidden; border:1px solid rgba(255,255,255,.09); background:#0d1017;
  font-family:ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;
  -webkit-tap-highlight-color:transparent;
}
.mo5-iris-wipe-stage{
  box-sizing:border-box; position:absolute; inset:0; display:block; width:100%; height:100%; margin:0; padding:0;
  border:0; background:#11151f; cursor:crosshair; overflow:hidden; border-radius:14px;
}
.mo5-iris-wipe-stage:focus-visible{outline:2px solid #fff; outline-offset:-3px}
.mo5-iris-wipe-layer{
  position:absolute; inset:0; display:block; overflow:hidden;
  -webkit-clip-path:circle(0px at 50% 50%); clip-path:circle(0px at 50% 50%);
  transition:-webkit-clip-path .8s cubic-bezier(.5,0,.15,1), clip-path .8s cubic-bezier(.5,0,.15,1);
  will-change:clip-path;
}
.mo5-iris-wipe-layer[data-on="1"]{-webkit-clip-path:circle(150% at 50% 50%); clip-path:circle(150% at 50% 50%)}
.mo5-iris-wipe-l1{background:linear-gradient(135deg,#2b1b5e,#4c1d95 45%,#1e1b4b)}
.mo5-iris-wipe-l2{background:linear-gradient(135deg,#4a1d16,#b3450f 48%,#2a1108)}
.mo5-iris-wipe-l3{background:linear-gradient(135deg,#0d3b3e,#0f766e 46%,#062226)}
.mo5-iris-wipe-orb{
  position:absolute; left:50%; top:50%; width:190px; height:190px; margin:-95px 0 0 -95px; border-radius:50%;
  background:radial-gradient(circle at 34% 30%, rgba(255,255,255,.4), rgba(255,255,255,.05) 42%, transparent 66%);
  animation:mo5-iris-wipe-drift 11s ease-in-out infinite alternate; filter:blur(2px);
}
.mo5-iris-wipe-l2 .mo5-iris-wipe-orb{animation-duration:9s; animation-direction:alternate-reverse}
.mo5-iris-wipe-l3 .mo5-iris-wipe-orb{animation-duration:13s}
.mo5-iris-wipe-txt{
  position:absolute; left:14px; bottom:14px; display:flex; flex-direction:column; gap:3px; text-align:left;
  text-shadow:0 2px 14px rgba(0,0,0,.55);
}
.mo5-iris-wipe-t{font-size:24px; font-weight:750; letter-spacing:-.025em; color:#fff; line-height:1}
.mo5-iris-wipe-s{font-size:9.5px; font-style:normal; letter-spacing:.16em; text-transform:uppercase; color:rgba(255,255,255,.72)}
.mo5-iris-wipe-ring{
  position:absolute; left:0; top:0; width:14px; height:14px; margin:-7px 0 0 -7px; border-radius:50%;
  border:2px solid rgba(255,255,255,.9); opacity:0; pointer-events:none;
}
