var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var stage = root.querySelector('.mo5-iris-wipe-stage');
var layers = Array.prototype.slice.call(root.querySelectorAll('.mo5-iris-wipe-layer'));
var dots = Array.prototype.slice.call(root.querySelectorAll('.mo5-iris-wipe-dot'));
var ring = root.querySelector('.mo5-iris-wipe-ring');
var cur = 0, z = 1, busy = false;

function clip(el, r, x, y) {
  var s = 'circle(' + r + 'px at ' + x + 'px ' + y + 'px)';
  el.style.webkitClipPath = s;
  el.style.clipPath = s;
}

function pulse(x, y, R) {
  if (reduce || !ring.animate) return;
  ring.style.transform = 'translate(' + x + 'px,' + y + 'px)';
  ring.animate(
    [{ opacity: .85, transform: 'translate(' + x + 'px,' + y + 'px) scale(.2)' },
     { opacity: 0, transform: 'translate(' + x + 'px,' + y + 'px) scale(' + (R / 5) + ')' }],
    { duration: 820, easing: 'cubic-bezier(.16,.8,.3,1)' }
  );
}

function intro(el, dir) {
  if (reduce || !el.animate) return;
  var t = el.querySelector('.mo5-iris-wipe-t');
  var s = el.querySelector('.mo5-iris-wipe-s');
  [t, s].forEach(function (n, i) {
    n.animate(
      [{ opacity: 0, transform: 'translate(' + (dir * 16) + 'px,6px)' }, { opacity: 1, transform: 'none' }],
      { duration: 620, delay: 180 + i * 110, easing: 'cubic-bezier(.2,.95,.3,1.05)', fill: 'backwards' }
    );
  });
}

function reveal(x, y) {
  if (busy) return;
  var r = stage.getBoundingClientRect();
  var w = r.width, h = r.height;
  if (x == null) { x = w * .5; y = h * .5; }
  var R = Math.sqrt(Math.pow(Math.max(x, w - x), 2) + Math.pow(Math.max(y, h - y), 2)) + 6;
  var next = (cur + 1) % layers.length;
  var el = layers[next];
  el.style.zIndex = String(++z);
  if (reduce) {
    layers.forEach(function (l, i) { l.setAttribute('data-on', i === next ? '1' : '0'); l.style.clipPath = ''; l.style.webkitClipPath = ''; });
  } else {
    busy = true;
    el.style.transition = 'none';
    clip(el, 0, x, y);
    void el.getBoundingClientRect();
    el.style.transition = '-webkit-clip-path .82s cubic-bezier(.5,0,.15,1), clip-path .82s cubic-bezier(.5,0,.15,1)';
    clip(el, R, x, y);
    pulse(x, y, R);
    intro(el, x < w * .5 ? -1 : 1);
    window.setTimeout(function () {
      layers.forEach(function (l, i) { if (i !== next) { l.setAttribute('data-on', '0'); l.style.transition = 'none'; clip(l, 0, w / 2, h / 2); } });
      el.style.transition = 'none';
      el.style.webkitClipPath = ''; el.style.clipPath = '';
      el.setAttribute('data-on', '1');
      busy = false;
    }, 840);
  }
  dots.forEach(function (d, i) { d.setAttribute('data-on', i === next ? '1' : '0'); });
  cur = next;
}

stage.addEventListener('click', function (e) {
  var r = stage.getBoundingClientRect();
  if (e.clientX === 0 && e.clientY === 0) reveal(null, null);
  else reveal(e.clientX - r.left, e.clientY - r.top);
});

layers[0].style.zIndex = '1';
if (!reduce) {
  layers[0].setAttribute('data-on', '0');
  layers[0].style.transition = 'none';
  clip(layers[0], 0, 0, 0);
  window.requestAnimationFrame(function () {
    if (!root.isConnected) return;
    var r = stage.getBoundingClientRect();
    var x = r.width * .5, y = r.height * .58;
    var R = Math.sqrt(Math.pow(Math.max(x, r.width - x), 2) + Math.pow(Math.max(y, r.height - y), 2)) + 6;
    layers[0].style.transition = '-webkit-clip-path .9s cubic-bezier(.5,0,.15,1), clip-path .9s cubic-bezier(.5,0,.15,1)';
    clip(layers[0], R, x, y);
    intro(layers[0], -1);
    window.setTimeout(function () {
      if (!root.isConnected) return;
      layers[0].style.transition = 'none';
      layers[0].style.webkitClipPath = ''; layers[0].style.clipPath = '';
      layers[0].setAttribute('data-on', '1');
    }, 940);
  });
}

