js:
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var book = root.querySelector('.mo5-page-fold-book');
var verso = root.querySelector('.mo5-page-fold-verso');
var recto = root.querySelector('.mo5-page-fold-recto');
var leaf = root.querySelector('.mo5-page-fold-leaf');
var front = root.querySelector('.mo5-page-fold-front');
var backFace = root.querySelector('.mo5-page-fold-back');
var fShade = front.querySelector('.mo5-page-fold-shade');
var bShade = backFace.querySelector('.mo5-page-fold-shade');
var num = root.querySelector('.mo5-page-fold-num');
var btns = Array.prototype.slice.call(root.querySelectorAll('.mo5-page-fold-btn'));

var TITLES = ['Prologue', 'The Fold', 'Hinge', 'Vellum', 'Spine', 'Signature', 'Deckle', 'Colophon'];
var SPREADS = TITLES.length / 2;
var spread = 0, angle = 0, busy = false, drag = null, dir = 1, timer = 0;

function noise(a, b) { var s = Math.sin(a * 12.9898 + b * 78.233) * 43758.5453; return s - Math.floor(s); }

function render(el, n) {
  el.querySelector('.mo5-page-fold-h').textContent = TITLES[n - 1] || '';
  el.querySelector('.mo5-page-fold-no').textContent = String(n);
  var lns = el.querySelectorAll('.mo5-page-fold-ln');
  for (var i = 0; i < lns.length; i++) {
    var w = i === lns.length - 1 ? 34 + noise(n, i) * 26 : 74 + noise(n, i) * 26;
    lns[i].style.width = w.toFixed(1) + '%';
  }
}

function paint() {
  render(verso, spread * 2 + 1);
  render(recto, spread * 2 + 2);
  num.textContent = (spread * 2 + 1) + ' – ' + (spread * 2 + 2) + ' of ' + TITLES.length;
  btns[0].disabled = spread === 0;
  btns[1].disabled = spread === SPREADS - 1;
}

function setAngle(a) {
  angle = a;
  leaf.style.transform = 'rotateY(' + a.toFixed(2) + 'deg)';
  var q = -a / 180;
  fShade.style.opacity = (q * .82).toFixed(3);
  bShade.style.opacity = ((1 - q) * .82).toFixed(3);
}

function setup(d) {
  if (d > 0 && spread >= SPREADS - 1) return false;
  if (d < 0 && spread <= 0) return false;
  dir = d;
  if (d > 0) {
    render(front, spread * 2 + 2);
    render(backFace, spread * 2 + 3);
    render(recto, spread * 2 + 4);
  } else {
    render(front, spread * 2);
    render(backFace, spread * 2 + 1);
    render(verso, spread * 2 - 1);
  }
  leaf.setAttribute('data-turning', '1');
  setAngle(d > 0 ? 0 : -180);
  return true;
}

function settle(commit) {
  leaf.setAttribute('data-turning', '0');
  if (commit) spread += dir;
  paint();
  setAngle(0);
  busy = false;
}

function ease(t) { return t < .5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2; }

function glide(to, dur, cb) {
  var from = angle, t0 = 0;
  function step(now) {
    if (!root.isConnected) return;
    if (!t0) t0 = now;
    var t = Math.min(1, (now - t0) / dur);
    setAngle(from + (to - from) * ease(t));
    if (t < 1) window.requestAnimationFrame(step); else cb();
  }
  window.requestAnimationFrame(step);
}

function turn(d) {
  if (busy || drag) return;
  if (!setup(d)) return;
  busy = true;
  if (reduce) { settle(true); return; }
  glide(d > 0 ? -180 : 0, 720, function () { settle(true); });
}

function schedule() {
  window.clearTimeout(timer);
  if (reduce) return;
  timer = window.setTimeout(function () {
    if (!root.isConnected) return;
    if (spread >= SPREADS - 1) dirAuto = -1;
    if (spread <= 0) dirAuto = 1;
    turn(dirAuto);
    schedule();
  }, 4200);
}
var dirAuto = 1;

btns.forEach(function (b) {
  b.addEventListener('click', function () { turn(Number(b.getAttribute('data-d'))); schedule(); });
});

book.addEventListener('pointerdown', function (e) {
  if (busy || reduce) return;
  var r = book.getBoundingClientRect();
  var d = (e.clientX - r.left) > r.width / 2 ? 1 : -1;
  if (!setup(d)) return;
  drag = { x: e.clientX, half: r.width / 2 };
  book.setAttribute('data-drag', '1');
  try { book.setPointerCapture(e.pointerId); } catch (err) {}
  window.clearTimeout(timer);
});
book.addEventListener('pointermove', function (e) {
  if (!drag) return;
  var dx = e.clientX - drag.x;
  var q = dir > 0 ? -dx / drag.half : 1 - dx / drag.half;
  q = q < 0 ? 0 : q > 1 ? 1 : q;
  setAngle(-180 * q);
});
function release() {
  if (!drag) return;
  drag = null;
  book.setAttribute('data-drag', '0');
  busy = true;
  var q = -angle / 180;
  var done = dir > 0 ? q > .45 : q < .55;
  var to = dir > 0 ? (done ? -180 : 0) : (done ? 0 : -180);
  glide(to, 420, function () { settle(done); schedule(); });
}
book.addEventListener('pointerup', release);
book.addEventListener('pointercancel', release);

paint();
setAngle(0);
if (!reduce) {
  window.setTimeout(function () { if (root.isConnected) { turn(1); schedule(); } }, 900);
}

