js:
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var scene = root.querySelector('.mo5-curtain-slats-scene');
var slats = root.querySelector('.mo5-curtain-slats-slats');
var btn = root.querySelector('.mo5-curtain-slats-btn');
var act = root.querySelector('.mo5-curtain-slats-act');
var title = root.querySelector('.mo5-curtain-slats-title');
var body = root.querySelector('.mo5-curtain-slats-body');

var ACTS = [
  { a: 'Act I', t: 'Overture', b: 'Nine slats close, the set changes, they lift.' },
  { a: 'Act II', t: 'Interval', b: 'Each slat leaves 34ms after the last.' },
  { a: 'Act III', t: 'Finale', b: 'Down to cover, up to reveal.' }
];
var i = 0, busy = false, t0 = 0, raf = 0;
var COVER = 400 + 8 * 34 + 40;
var CYCLE = 4600;

function paint(n) {
  scene.setAttribute('data-scene', String(n));
  act.textContent = ACTS[n].a;
  title.textContent = ACTS[n].t;
  body.textContent = ACTS[n].b;
}

function reveal() {
  if (reduce || !title.animate) return;
  [act, title, body].forEach(function (el, k) {
    el.animate(
      [{ opacity: 0, transform: 'translateY(16px)' }, { opacity: 1, transform: 'none' }],
      { duration: 620, delay: 190 + k * 95, easing: 'cubic-bezier(.2,.98,.3,1)', fill: 'backwards' }
    );
  });
}

function wipe() {
  if (busy) return;
  busy = true;
  t0 = 0;
  if (reduce) { i = (i + 1) % ACTS.length; paint(i); busy = false; return; }
  slats.setAttribute('data-state', 'in');
  window.setTimeout(function () {
    if (!root.isConnected) return;
    i = (i + 1) % ACTS.length;
    paint(i);
    slats.setAttribute('data-state', 'out');
    reveal();
    window.setTimeout(function () { busy = false; t0 = 0; }, COVER);
  }, COVER);
}

function loop(now) {
  if (!root.isConnected) return;
  if (!t0) t0 = now;
  var p = (now - t0) / CYCLE;
  if (p >= 1 && !busy) { wipe(); p = 0; }
  root.style.setProperty('--mo5-cs-p', String(busy ? 0 : Math.max(0, Math.min(1, p))));
  raf = window.requestAnimationFrame(loop);
}

btn.addEventListener('click', function () { if (!busy) { wipe(); t0 = 0; } });

paint(0);
if (reduce) { root.style.setProperty('--mo5-cs-p', '1'); }
else { reveal(); raf = window.requestAnimationFrame(loop); }

