var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var deck = root.querySelector('.mo5-deal-stack-deck');
var act = root.querySelector('.mo5-deal-stack-act');
var note = root.querySelector('.mo5-deal-stack-note');
var cards = Array.prototype.slice.call(root.querySelectorAll('.mo5-deal-stack-card'));
var dealt = false;

function clear() {
  cards.forEach(function (c) { c.setAttribute('aria-pressed', 'false'); });
}

function shuffle() {
  cards.forEach(function (c, i) {
    var spread = (i - (cards.length - 1) / 2);
    c.style.setProperty('--mo5-ds-r', (spread * 5.5 + (Math.random() - .5) * 3).toFixed(2) + 'deg');
    c.style.setProperty('--mo5-ds-ty', (Math.abs(spread) * 2.4 - 2 + (Math.random() - .5) * 2).toFixed(2) + 'px');
    c.style.setProperty('--mo5-ds-s', ((Math.random() - .5) * 7).toFixed(2) + 'deg');
  });
}

function set(on) {
  dealt = on;
  if (!on) clear();
  else shuffle();
  deck.setAttribute('data-dealt', on ? '1' : '0');
  act.textContent = on ? 'Collect' : 'Deal';
  note.textContent = on ? '5 cards · 70ms stagger' : 'tap deal to fan out';
}

act.addEventListener('click', function () { set(!dealt); });

cards.forEach(function (c) {
  c.addEventListener('click', function () {
    if (!dealt) { set(true); return; }
    var on = c.getAttribute('aria-pressed') === 'true';
    clear();
    c.setAttribute('aria-pressed', on ? 'false' : 'true');
    if (!on && !reduce && c.animate) {
      c.animate(
        [{ filter: 'brightness(1)' }, { filter: 'brightness(1.35)' }, { filter: 'brightness(1)' }],
        { duration: 520, easing: 'ease-out' }
      );
    }
  });
});

if (reduce) { set(true); }
else { window.setTimeout(function () { if (root.isConnected) set(true); }, 480); }

