var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var slides = Array.prototype.slice.call(root.querySelectorAll('.mo5-xfade-scale-slide'));
var dots = Array.prototype.slice.call(root.querySelectorAll('.mo5-xfade-scale-dot'));
var cur = 0, paused = false, elapsed = 0, last = 0;
var HOLD = 3800;

function caption(el) {
  if (reduce || !el.animate) return;
  var parts = el.querySelectorAll('.mo5-xfade-scale-idx, .mo5-xfade-scale-t, .mo5-xfade-scale-d');
  for (var i = 0; i < parts.length; i++) {
    parts[i].animate(
      [{ opacity: 0, transform: 'translateY(14px) scale(.96)' }, { opacity: 1, transform: 'none' }],
      { duration: 640, delay: 140 + i * 90, easing: 'cubic-bezier(.18,.98,.28,1)', fill: 'backwards' }
    );
  }
}

function show(n) {
  elapsed = 0;
  if (n === cur) return;
  var prev = slides[cur];
  prev.removeAttribute('data-on');
  prev.setAttribute('data-out', '1');
  window.setTimeout(function () { if (root.isConnected) prev.removeAttribute('data-out'); }, 840);
  cur = n;
  slides[n].setAttribute('data-on', '1');
  caption(slides[n]);
  dots.forEach(function (d, i) { d.setAttribute('aria-current', i === n ? 'true' : 'false'); });
}

function tick(now) {
  if (!root.isConnected) return;
  if (!last) last = now;
  var dt = Math.min(120, now - last);
  last = now;
  if (!paused) elapsed += dt;
  var p = Math.max(0, Math.min(1, elapsed / HOLD));
  root.style.setProperty('--mo5-xf-p', String(p));
  if (p >= 1) show((cur + 1) % slides.length);
  window.requestAnimationFrame(tick);
}

dots.forEach(function (d, i) {
  d.addEventListener('click', function () { show(i); });
});
root.addEventListener('pointerenter', function () { paused = true; });
root.addEventListener('pointerleave', function () { paused = false; });
root.addEventListener('focusin', function () { paused = true; });
root.addEventListener('focusout', function () { paused = false; });

if (reduce) { root.style.setProperty('--mo5-xf-p', '1'); }
else { caption(slides[0]); window.requestAnimationFrame(tick); }

