js:
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var items = Array.prototype.slice.call(root.querySelectorAll('.mo5-true-accordion-item'));
var mark = root.querySelector('.mo5-true-accordion-mark');
var rail = root.querySelector('.mo5-true-accordion-rail');
var EASE = 'cubic-bezier(.22,1,.36,1)';
var open = -1;

var parts = items.map(function (it) {
  return {
    head: it.querySelector('.mo5-true-accordion-head'),
    panel: it.querySelector('.mo5-true-accordion-panel'),
    inner: it.querySelector('.mo5-true-accordion-inner'),
    rows: Array.prototype.slice.call(it.querySelectorAll('.mo5-true-accordion-row'))
  };
});

function height(el) { return el.getBoundingClientRect().height; }

// centre the marker on a head, in the rail's own coordinate space
function markY(h) { return h.offsetTop - rail.offsetTop + (h.offsetHeight - mark.offsetHeight) / 2; }

// the height is committed first so layout is final, then replayed from the old value
function play(panel, from, to, dur) {
  if (reduce || !panel.animate || from === to) return;
  panel.animate([{ height: from + 'px' }, { height: to + 'px' }], { duration: dur, easing: EASE });
}

function rows(p) {
  if (reduce || !p.rows[0] || !p.rows[0].animate) return;
  p.rows.forEach(function (r, i) {
    r.animate(
      [{ opacity: 0, transform: 'translateY(10px)' }, { opacity: 1, transform: 'none' }],
      { duration: 460, delay: 90 + i * 55, easing: EASE, fill: 'backwards' }
    );
  });
}

function toggle(n) {
  var was = open;
  var p = parts[n];

  if (was === n) {
    open = -1;
    p.head.setAttribute('aria-expanded', 'false');
    var f0 = height(p.panel);
    p.panel.style.height = '0px';
    play(p.panel, f0, 0, 320);
    mark.setAttribute('data-on', '0');
    return;
  }

  open = n;
  var fw = was >= 0 ? height(parts[was].panel) : 0;
  var fn = height(p.panel);
  var target = height(p.inner);

  if (was >= 0) {
    parts[was].head.setAttribute('aria-expanded', 'false');
    parts[was].panel.style.height = '0px';
  }
  p.head.setAttribute('aria-expanded', 'true');
  p.panel.style.height = target + 'px';

  // layout is settled here - nothing is animating yet
  mark.setAttribute('data-on', '1');
  mark.style.transform = 'translateY(' + markY(p.head).toFixed(1) + 'px)';

  if (was >= 0) play(parts[was].panel, fw, 0, 300);
  play(p.panel, fn, target, 460);
  rows(p);
}

parts.forEach(function (p, i) {
  p.head.addEventListener('click', function () { toggle(i); });
});

if (reduce) { toggle(0); }
else { window.setTimeout(function () { if (root.isConnected) toggle(0); }, 320); }
